    function verifyProof(
        address user,
        uint[2] calldata _pA,
        uint[2][2] calldata _pB,
        uint[2] calldata _pC,
        uint[2] calldata _pubSignals,
        bytes32 sm3Hash
    ) public returns (bool) {
        // Parameter validation
        require(sm3Hash != bytes32(0), "SM3 hash cannot be empty");

        bool isValid = _verifyProofInternal(_pA, _pB, _pC, _pubSignals);

        if (isValid) {
            emit ProofVerifySuccess(user, sm3Hash, block.timestamp);
        }

        return isValid;
    }

    function _verifyProofInternal(uint[2] calldata _pA, uint[2][2] calldata _pB, uint[2] calldata _pC, uint[2] calldata _pubSignals) internal view returns (bool) {
        assembly {
            function checkField(v) {
                if iszero(lt(v, r)) {
                    mstore(0, 0)
                    return(0, 0x20)
                }
            }

